def get_region_corners(grid, row_divs, col_divs, or_idx, oc_idx):
    """Get the 4 corner cells of a region"""
    h, w = len(grid), len(grid[0])

    if or_idx == 0:
        r_start = 0
    else:
        r_start = row_divs[or_idx-1] + 1

    if or_idx == len(row_divs):
        r_end = h - 1
