    if oc_idx == len(col_divs):
        c_end = w - 1
    else:
        c_end = col_divs[oc_idx]

    # Get 4 corner 2x2 blocks
    corners = set()

    # Top-left corner
    corners.add(grid[r_start][c_start])

    # If region has enough space, add more corner cells
    if r_start + 1 < h and c_start + 1 < w:
        corners.add(grid[r_start+1][c_start])
        corners.add(grid[r_start][c_start+1])
        corners.add(grid[r_start+1][c_start+1])

    # Bottom-left corner
    if r_end - 1 >= 0:
        corners.add(grid[r_end-1][c_start])
        if c_start + 1 < w:
