from collections import deque

# Rule hypothesis: Start from neighbors of (0,0), BFS everything reachable except (0,0) itself and the grid corner
def test_rule(hro, hcol, name):
    if name == "Demo 1":
        special_regions = {(0,0)}
    else:
        special_regions = {(0,1), (1,0), (1,1), (2,0)}

    # BFS from (0,0)'s neighbors, NEVER entering (0,0), Never entering lower-right corner
    start_neighbors = [(0, 1), (1, 0)]
    visited = set(start_neighbors)
    queue = deque(start_neighbors)

    while queue:
        r, c = queue.popleft()
        # Add all 8 neighbors (including diagonals)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                # Bounds check
                if not (0 <= nr < hro and 0 <= nc < hcol):
                    continue
                # NEVER enter (0,0)
                if (nr, nc) == (0, 0):
                    continue
                # Never enter the corner
                if (nr, nc) == (hro - 1, hcol - 1):
                    continue
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    predicted = visited
    match = predicted == special_regions
    print(f"{name} {hro}x{hcol}: Predicted={sorted(predicted)}, Actual={sorted(special_regions)}, Match={match}")
    return match

# Test both demos
